import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, uniform, smoothstep, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, RoundedBoxGeometry, Color, Vector3 } = THREE;

  const root = new Group();
  root.name = 'journal-quote-panel';

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // ── Gradient backdrop (STAGE, never void) ────────────────────────────────
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(
    vec3(colors.surface),
    vec3(colors.ink),
    uv().y
  );
  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ── Card group (animated child so scenePosition stays intact) ────────────
  const card = new Group();
  card.name = 'quote-card';
  root.add(card);

  const W = 2.2, H = 1.4, D = 0.08;

  // Machined-metal frame (bevel + PBR)
  const frameMat = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.22,
    clearcoatRoughness: 0.55,
  });
  const frame = new Mesh(new RoundedBoxGeometry(W, H, D, 6, 0.04), frameMat);
  frame.castShadow = true;
  frame.receiveShadow = true;
  card.add(frame);

  // Image front face (image displays true, no shading on the photo)
  const imgPlaneMat = new MeshBasicNodeMaterial({ transparent: true });
  const imgPlane = new Mesh(new PlaneGeometry(W - 0.12, H - 0.12), imgPlaneMat);
  imgPlane.position.z = D / 2 + 0.002;
  card.add(imgPlane);

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        tex.colorSpace = THREE.SRGBColorSpace;
        imgPlaneMat.map = tex;
        imgPlaneMat.needsUpdate = true;
      })
      .catch(() => {});
  }

  // Accent edge strip — left side
  const accentMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.9,
    metalness: 0.4,
    roughness: 0.45,
  });
  const accentEdge = new Mesh(
    new RoundedBoxGeometry(0.05, H - 0.16, D + 0.002, 4, 0.012),
    accentMat
  );
  accentEdge.position.set(-(W / 2) + 0.03, 0, 0);
  accentEdge.userData.focused = false;
  card.add(accentEdge);

  // Contact shadow plane under the card
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.5 });
  const shadowCtx = uniform(float(0.5));
  const sd = smoothstep(float(0.85), float(0.0), uv().x.mul(2.0).sub(1.0)).mul(
    smoothstep(float(0.85), float(0.0), uv().y.mul(2.0).sub(1.0))
  );
  shadowMat.colorNode = vec3(0, 0, 0).mul(sd);
  shadowMat.opacityNode = sd.mul(shadowCtx);
  const shadow = new Mesh(new PlaneGeometry(W * 1.5, H * 1.5), shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -H / 2 - 0.02, -D / 2);
  card.add(shadow);

  // ── Local lighting: rim + accent (scene provides ambient + key) ───────────
  const rim = new THREE.DirectionalLight(0xffffff, 0.7);
  rim.position.set(-2.5, 1.8, 2.0);
  root.add(rim);

  const accentRim = new THREE.PointLight(new Color(colors.accent), 0.9, 6, 1.5);
  accentRim.position.set(-1.6, 0.2, 1.2);
  root.add(accentRim);

  const fill = new THREE.HemisphereLight(0x303045, 0x05050a, 0.5);
  root.add(fill);

  // ── Cinematic primitive: parallax-scroll ────────────────────────────────
  const primResults = [];
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    if (p.name && ctx.primitives && ctx.primitives[p.name]) {
      const r = ctx.primitives[p.name](card, p.params ?? {});
      if (r) primResults.push(r);
    }
  }

  // ── Motion / interaction ─────────────────────────────────────────────────
  const tlHoverIn = gsap.timeline({ paused: true });
  tlHoverIn.to(card.position, {
    y: 0.15,
    duration: 0.45,
    ease: 'power3.out',
  });
  tlHoverIn.to(accentEdge.scale, {
    y: 1.0,
    duration: 0.4,
    ease: 'power2.out',
    onStart: () => { accentEdge.userData.focused = true; gsap.to(accentMat, { emissiveIntensity: 1.6, duration: 0.3 }); },
  }, 0);

  const tlHoverOut = gsap.timeline({ paused: true });
  tlHoverOut.to(card.position, { y: 0, duration: 0.5, ease: 'power3.out' });
  tlHoverOut.to(accentMat, { emissiveIntensity: 0.9, duration: 0.3 }, 0);

  let hovering = false;

  function onHover(e) {
    hovering = true;
    tlHoverOut.pause();
    tlHoverIn.restart();
  }
  function onHoverOut(e) {
    if (!hovering) return;
    hovering = false;
    tlHoverIn.pause();
    tlHoverOut.restart();
  }
  function onClick(e) {
    gsap.to(card.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
      yoyo: true,
      repeat: 1,
      onComplete: () => {
        gsap.to(card.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'power4.out' });
      },
    });
    ctx.emit('hub-journal.select', { source: 'journal-quote-panel' });
  }

  root.userData.handlers = {
    hover: onHover,
    hoverout: onHoverOut,
    click: onClick,
  };

  // Entrance settle
  card.position.y = 0.4;
  gsap.to(card.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
    delay: 0.1,
  });
  card.scale.set(1.04, 1.04, 1.04);
  gsap.to(card.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
    delay: 0.18,
  });

  // ── Cleanup ──────────────────────────────────────────────────────────────
  root.userData.cleanup = () => {
    tlHoverIn.kill(); tlHoverOut.kill();
    gsap.killTweensOf(card.position);
    gsap.killTweensOf(card.scale);
    gsap.killTweensOf(accentMat);
    primResults.forEach((r) => r && r.cleanup && r.cleanup());
    backdropMat.dispose(); frameMat.dispose(); imgPlaneMat.dispose();
    accentMat.dispose(); shadowMat.dispose();
    backdrop.geometry.dispose(); frame.geometry.dispose();
    imgPlane.geometry.dispose(); accentEdge.geometry.dispose();
    shadow.geometry.dispose();
    [rim, accentRim, fill].forEach((l) => l.dispose && l.dispose());
  };

  return root;
}
